import React, { Component } from 'react';
import Card from './card';
import './card.css';

class CardGrid extends Component {

    render = () => (
        <div className="card-grid">
            {
                this.props.posts.map((post, key) => {
                    console.log(post);
                    return (<Card key={key} heading={post.node.frontmatter.title} skillset={post.node.frontmatter.skillset} synopsis={post.node.frontmatter.synopsis}></Card>)
                })
            }
      </div>
    )

}

export default CardGrid